import { _decorator, Component, Font, Label, Layout, Node, Toggle, UITransform } from 'cc';
import SelectBetViewModel from './SelectBetViewModel';
import { EFFECTSMAP } from '../../audio/SOUNDMAP';
import AppAudio from '../../audio/AppAudio';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';
const { ccclass, property } = _decorator;

@ccclass('slot/1001/SelectBetView')
export class SelectBetView extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供 SelectBetViewModel 呼叫 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Font)
    selectFont: Font = null;
    @property(Font)
    defaultFont: Font = null;

    @property(Node)
    container: Node = null;

    viewModel: SelectBetViewModel;
    protected override start(): void {
        this.viewModel = new SelectBetViewModel(this);
    }
    protected override onLoad(): void {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_POPUP);
    }

    addItem(item: Node) {
        this.container.addChild(item);
    }
    exit() {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_CLOSE);
        this.node.destroy();
    }

    setSeclectState(item: Node) {
        console.log('set select state');
        item.getChildByName('Toggle').getComponent(Toggle).isChecked = true;
        item.getChildByName('Amount').getComponent(Label).font = this.selectFont;
    }
    setDefaultState(item: Node) {
        item.getChildByName('Toggle').getComponent(Toggle).isChecked = false;
        item.getChildByName('Amount').getComponent(Label).font = this.defaultFont;
    }

    setStyle(y) {
        this.node.y = y;
    }
}
