import { _decorator, Component, JsonAsset } from 'cc';
import type { BundleVersionInfo } from './BundleVersionInfo';

const { ccclass, property } = _decorator;

/**
 * WebBundleVersionChecker
 *
 * Web 平台對應原生 project.manifest／version.manifest
 * localVersion 內建的基準版本資訊（由 generate-bundle-manifest.mjs
 * 產生的 version.json 匯入 拿到的 packageUrl 已經是
 * 完整的版本資料夾網址 直接交給 AppAssetBundle.loadBundle() 當來源網址用
 * 不用另外拼版本號 也不需要 Cocos 的 md5Cache／bundleVers
 */
@ccclass('WebBundleVersionChecker')
export class WebBundleVersionChecker extends Component {
    @property(JsonAsset)
    public localVersion: JsonAsset = null!;

    /** 取得遠端實際要載入的 bundle 網址。 */
    public async resolveBundleUrl(): Promise<string> {
        const local = this.localVersion.json as unknown as BundleVersionInfo;
        try {
            const remote = await this.fetchRemoteVersion(local.remoteVersionUrl);
            if (remote.bundleName !== local.bundleName) {
                throw new Error(`bundleName 不符: ${remote.bundleName}`);
            }
            const pathname = new URL(remote.packageUrl).pathname.replace(/\/+$/, '');
            const urlBundleName = pathname.slice(pathname.lastIndexOf('/') + 1);
            if (urlBundleName !== local.bundleName) {
                throw new Error(`packageUrl 必須以 /${local.bundleName}/ 結尾，目前是 ${remote.packageUrl}`);
            }
            return remote.packageUrl;
        } catch (err) {
            // 不要嘗試載入格式錯誤的版本 URL，否則 Cocos 會用 URL
            // 最後一段當 bundle 名，後續再載入正常 1001 時就會重複
            // 執行 index.js。把錯誤交給上層，上層會回到原本可用的進場流程。
            console.warn('[WebBundleVersionChecker] 遠端版本資訊不可用，略過這次熱更', err);
            throw err;
        }
    }

    private async fetchRemoteVersion(remoteVersionUrl: string): Promise<BundleVersionInfo> {
        const res = await fetch(`${remoteVersionUrl}?t=${Date.now()}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return (await res.json()) as BundleVersionInfo;
    }
}
