import { _decorator, Button, Node } from 'cc';
import { EventComponent } from '../../events/EventComponent';
import { PopupStack } from './PopupStack';
import { PopupProperty } from './PopupProperty';

const { ccclass, property } = _decorator;

/**
 * PopupBase — 遊戲內彈窗共用基底。
 *
 * 提供標題／關閉鈕／（選配）返回鈕／（選配）背景遮罩點擊關閉這幾個所有彈窗
 * 共通的部分。具體彈窗（AutoPlayPopup／SystemMenuPopup／LeaveConfirmPopup／
 * 遊戲內彈窗可繼承這個類別，把自己的內容掛在 contentRoot 底下，`onLoad()`
 * 記得呼叫 `super.onLoad()` 再接自己的邏輯。
 *
 * 拆圖規格（拆圖備注）裡的四種彈窗共通元素只有：九宮格背景（prefab 自己套，
 * 不需要程式碼介入）、標題文字、右上角關閉鈕；返回鈕跟背景遮罩點擊關閉是
 * 選配（AUTO PLAY／系統選單／離開確認沒有返回鈕，選座位有）。
 */
@ccclass('slot/1001/core/framework/PopupBase')
export class PopupBase extends EventComponent {
    private property: PopupProperty = null!;

    protected override onLoad(): void {
        this.property = this.getComponentInChildren(PopupProperty) ?? null;

        this.property?.closeNode.on(Button.EventType.CLICK, this.close, this);
        this.trackDisposer(() => {
            if (this.property?.closeNode?.isValid) this.property.closeNode.off(Button.EventType.CLICK, this.close, this);
        });

        if (this.property?.backNode) {
            this.property.backNode.on(Button.EventType.CLICK, this.onBackClick, this);
            this.trackDisposer(() => {
                if (this.property?.backNode?.isValid) this.property.backNode.off(Button.EventType.CLICK, this.onBackClick, this);
            });
        }

        if (this.property?.maskNode) {
            this.property.maskNode.on(Node.EventType.TOUCH_END, this.onMaskClick, this);
            this.trackDisposer(() => {
                if (this.property?.maskNode?.isValid) this.property.maskNode.off(Node.EventType.TOUCH_END, this.onMaskClick, this);
            });
        }
    }

    /** 關閉彈窗，交給 PopupStack 統一處理（同步移出堆疊＋銷毀節點）；
     *  要做關閉動畫的彈窗可以覆寫這個方法，動畫播完後仍要呼叫 PopupStack.closeNode(this.node) */
    close(): void {
        PopupStack.closeNode(this.node);
    }

    /** 返回鈕預設行為＝關閉；有上一層可以回的彈窗（例如選座位要回選單）覆寫這個 */
    protected onBackClick(): void {
        this.close();
    }

    /** 背景遮罩點擊預設＝關閉；不想讓玩家點外部關閉的彈窗把 maskNode 留空即可，不會呼叫到這裡 */
    protected onMaskClick(): void {
        this.close();
    }
}
