import { _decorator, type Camera } from 'cc';
import { EventComponent } from '../../../../scripts/events/EventComponent';
import type { IGameMain } from './IGameMain';
import type { GameState } from '../../../../scripts/states/GameState';
import AppAudio from '../../../../scripts/audio/AppAudio';
import { DualViewController } from '../../../../scripts/controllers/DualViewController';
import StoreManager from '../../../../scripts/store/StoreManager';

const { ccclass } = _decorator;

/**
 * GameMain（共用基底，生命週期骨架 + 最小狀態機）
 *
 * 比照舊專案（Cocos_2022）SGEngine 的 GameMain：提供單例存取，以及
 * gameInit() -> enterGame() 的進場流程、exitGame() 的收尾流程；並實作
 * IGameMain 的狀態機部分（hasState/getCurStateKey/changeState），比照舊專案
 * GameMain 的 stateMap/curState/changeState()。
 *
 * 範圍限定：舊專案 GameMain 的 frame-tick GameTask 佇列、GameComponent 陣列
 * 註冊制、sound()/playBGM() 等周邊不在此共用之列，各遊戲仍使用既有的
 * GameTaskQueue（Promise-based）。cascade、免費遊戲等實際流程邏輯留在各自的
 * GameMain_<gameId> 子類別，不在此共用。
 *
 * 使用方式：各遊戲的 GameMain_<gameId> 繼承本類別，實作 gameInit()/enterGame()；
 * 在 gameInit() 內呼叫 registerState() 註冊自己的 GameState 子類別實體
 * （純 TS 類別，不需要場景節點），需要額外收尾邏輯時覆寫 exitGame() 並呼叫
 * super.exitGame() 以清空單例。
 *
 * TView（各遊戲自己的 GameViewAdapter 具體型別）：泛型只用來支援 dualView（見下方
 * DualViewController 說明），跟遊戲類型（slot/桌遊等）無關，任何遊戲都可以直接繼承。
 */
@ccclass('slot/1001/core/framework/GameMain')
export abstract class GameMain<TView extends object> extends EventComponent implements IGameMain {
    private static _instance: GameMain<any> | null = null;

    /** 目前作用中的 GameMain 實體（同時間只會有一款遊戲在執行） */
    public static get instance(): GameMain<any> | null {
        return GameMain._instance;
    }

    protected abstract get viewH(): TView;
    protected abstract get viewV(): TView | null;

    /**
     * 雙向 Proxy — 操作會同時作用於 viewH 與 viewV，跟目前哪個 view 正在顯示無關
     * （顯示層面的直橫版切換屬於 OrientationController，留在需要的遊戲子類別自己接線）。
     */
    private dualViewCtrl: DualViewController<TView> = new DualViewController({
        getViewH: () => this.viewH,
        getViewV: () => this.viewV,
    });
    protected get dualView(): TView {
        return this.dualViewCtrl.view;
    }

    /** public：供 Net/Task/* 存取；各遊戲自己在 gameInit() 賦值（比照 StoreManager.getInstance()） */
    public storeManager: StoreManager = null!;

    /** 遊戲主攝影機參考，各遊戲自己在 gameInit() 賦值；跟遊戲類型無關 */
    protected mainCamera: Camera | null = null;

    /** 取得所有 view（含 viewV，若存在）。public：供 Net/Task/* 存取 */
    public get allViews(): TView[] {
        return this.viewV ? [this.viewH, this.viewV] : [this.viewH];
    }

    /** 對所有 view 執行操作。public：供 Net/Task/* 存取 */
    public forEachView(fn: (v: TView) => void): void {
        for (const v of this.allViews) {
            try {
                fn(v);
            } catch (e) {
                console.warn('[GC] forEachView error:', e);
            }
        }
    }

    private readonly stateMap = new Map<string, GameState<IGameMain>>();
    private curStateKey: string | null = null;
    private curState: GameState<IGameMain> | null = null;

    /** 註冊一個狀態（於 gameInit() 內呼叫），註冊當下就會呼叫該狀態的 init() 注入 game 參考 */
    protected registerState(stateKey: string, state: GameState<IGameMain>): void {
        state.init(this);
        this.stateMap.set(stateKey, state);
    }

    public hasState(stateKey: string): boolean {
        return this.stateMap.has(stateKey);
    }

    public getCurStateKey(): string | null {
        return this.curStateKey;
    }

    public changeState(stateKey: string): void {
        if (this.curStateKey === stateKey) return;

        const next = this.stateMap.get(stateKey);
        if (!next) {
            console.warn(`[GameMain] changeState('${stateKey}') 失敗：找不到已註冊的狀態`);
            return;
        }

        this.curState?.exit();
        this.curStateKey = stateKey;
        this.curState = next;
        this.curState.enter();
    }

    protected override onLoad(): void {
        super.onLoad?.();
        GameMain._instance = this;
    }

    public override onDestroy(): void {
        this.exitGame();
        super.onDestroy();
    }

    protected override start(): void {
        this.gameInit();
        this.enterGame();
    }

    /** 遊戲初始化：建立 model/viewModel、綁定輸入與事件訂閱（比照舊專案 GameMain 的 gameInit()） */
    protected abstract gameInit(): void;

    /** 進入遊戲：啟動音樂、背景與 UI 呈現（比照舊專案 GameMain 的 doEnterGame()/onEnterGame()） */
    protected abstract enterGame(): void;

    /** 離開遊戲收尾（比照舊專案 GameMain 的 exitGame()/gameFini()）；子類別覆寫時記得呼叫 super.exitGame() */
    protected exitGame(): void {
        AppAudio.stopCurrent();
        GameMain._instance = null;
    }
}
