import { _decorator, Component, Label, Node, Slider, sys, UITransform } from 'cc';
import AppAssetBundle from '../utils/AppAssetBundle';
import {
    HOT_UPDATE_ENABLED_BUNDLES,
    NATIVE_CHECK_TIMEOUT_MS,
    NATIVE_DOWNLOAD_STALL_TIMEOUT_MS,
    NATIVE_HOT_UPDATE_CHECK_ENABLED,
    WEB_HOT_UPDATE_CHECK_ENABLED,
} from './HotUpdateConfig';
import { NativeBundleUpdater, NativeUpdateResult } from './NativeBundleUpdater';
import { WebBundleVersionChecker } from './WebBundleVersionChecker';

const { ccclass, property } = _decorator;

/** 重啟後要接續進場的資訊 跟 entry LoadingScene 讀的是同一把 localStorage key／同一種形狀 */
interface PendingRestartEntry {
    bundle: string;
    scene: string;
}

const RESTART_STORAGE_KEY = 'pending_game_entry_for_restart';

/**
 * GameBundleUpdateView
 *
 * 從 entry 搬過來 原本掛在大廳桌列表場景 由 entry 呼叫；現在改成 1001
 * 自己的元件 進場前自己檢查有沒有新版 Web 走 WebBundleVersionChecker
 * 比對版本後拿到完整的版本資料夾網址 直接用 AppAssetBundle.loadBundle(url)
 * 從那個網址載入 原生走 NativeBundleUpdater 下載完成後 game.restart（重啟後
 * 要接續進場的資訊寫進 localStorage 不再透過 entry 的 PendingGameEntry 類別 因為
 * 這裡是獨立的 slot_game 專案 拿不到那個類別 兩邊靠同一把 storage key 銜接）
 */
@ccclass('GameBundleUpdateView')
export class GameBundleUpdateView extends Component {
    private static instance: GameBundleUpdateView | null = null;

    public static getInstance(): GameBundleUpdateView | null {
        return GameBundleUpdateView.instance;
    }

    @property({ type: Node, tooltip: '整個更新畫面的根節點 預設隱藏' })
    public panelRoot: Node = null!;

    @property(Slider)
    public progressSlider: Slider = null!;

    @property(UITransform)
    public progressTransform: UITransform = null!;

    @property(Label)
    public progressLabel: Label = null!;

    @property(Label)
    public statusLabel: Label = null!;

    @property(NativeBundleUpdater)
    public nativeUpdater: NativeBundleUpdater = null!;

    @property(WebBundleVersionChecker)
    public webChecker: WebBundleVersionChecker = null!;

    private barMaxWidth = 500;

    protected override onLoad(): void {
        GameBundleUpdateView.instance = this;
        if (this.progressTransform?.width > 0) {
            this.barMaxWidth = this.progressTransform.width;
        }
        if (!this.nativeUpdater) {
            console.warn('[GameBundleUpdateView] nativeUpdater 尚未在 Inspector 指定 原生熱更檢查會直接略過');
        }
        this.hide();
    }

    protected override onDestroy(): void {
        if (GameBundleUpdateView.instance === this) GameBundleUpdateView.instance = null;
    }

    /**
     * 檢查並在需要時執行熱更 總開關關閉或 bundle 不在白名單內忽略
     * 檢查過程任何失敗（逾時 網路錯誤 屬性沒接）都只記警告 不會擋住呼叫方
     * 讓玩家照本地既有版本正常進場 原生更新真的成功會呼叫 game.restart
     * 這個 Promise 不會 resolve 交由重啟後的啟動流程接續
     */
    public async ensureUpdated(pending: PendingRestartEntry): Promise<void> {
        const bundleName = pending.bundle;
        if (!bundleName || !HOT_UPDATE_ENABLED_BUNDLES.has(bundleName)) return;
        if (sys.isNative ? !NATIVE_HOT_UPDATE_CHECK_ENABLED : !WEB_HOT_UPDATE_CHECK_ENABLED) return;

        this.show();
        this.setStatus('檢查更新中...');
        try {
            if (sys.isNative) {
                await this.runNativeUpdate(pending);
            } else {
                await this.runWebUpdate(pending);
            }
        } catch (err) {
            console.warn(`[GameBundleUpdateView] "${bundleName}" 熱更檢查失敗 改用本地既有版本正常進場`, err);
        } finally {
            this.hide();
        }
    }

    private async runNativeUpdate(pending: PendingRestartEntry): Promise<void> {
        if (!this.nativeUpdater) {
            console.warn('[GameBundleUpdateView] nativeUpdater 尚未在 Inspector 指定 略過原生熱更檢查');
            return;
        }
        sys.localStorage.setItem(RESTART_STORAGE_KEY, JSON.stringify(pending));
        try {
            const result = await this.checkAndUpdateWithTimeout();
            if (result === NativeUpdateResult.UpToDate) {
                sys.localStorage.removeItem(RESTART_STORAGE_KEY);
                return;
            }
            // game.restart() 不會同步終止當前 JS，阻止呼叫方又繼續進場。
            await new Promise<void>(() => {});
        } catch (err) {
            sys.localStorage.removeItem(RESTART_STORAGE_KEY);
            throw err;
        }
    }

    /**
     * 逾時分兩段 不能整個 checkAndUpdate 逾時代表查詢本身卡住了
     *
     * 下載階段（NATIVE_DOWNLOAD_STALL_TIMEOUT_MS）：一旦確認有新版本開始真的
     * 下載 就不該再用「總長度」限制——改成「多久沒有新進度」 每次收到
     * UPDATE_PROGRESSION 都重新計時 真的卡住（網路斷了、伺服器沒回應）才會
     * 逾時 正常下載不管檔案多大、多久，只要進度持續前進就不會被打斷
     *
     * 逾時（不管哪一段）都呼叫 cancel 讓晚到的事件不再生效 避免
     * UPDATE_FINISHED 觸發非預期的 game.restart
     */
    private checkAndUpdateWithTimeout(): Promise<NativeUpdateResult> {
        return new Promise((resolve, reject) => {
            let timer: ReturnType<typeof setTimeout>;
            const onTimeout = (message: string): void => {
                this.nativeUpdater.cancel();
                reject(new Error(message));
            };
            const resetTimer = (message: string, ms: number): void => {
                clearTimeout(timer);
                timer = setTimeout(() => onTimeout(message), ms);
            };

            resetTimer('原生熱更版本檢查逾時', NATIVE_CHECK_TIMEOUT_MS);

            this.nativeUpdater.onCheckResolved = () => {
                resetTimer('原生熱更下載逾時（太久沒有新進度）', NATIVE_DOWNLOAD_STALL_TIMEOUT_MS);
            };
            this.nativeUpdater.onProgress = (percent) => {
                this.updateProgress(percent);
                resetTimer('原生熱更下載逾時（太久沒有新進度）', NATIVE_DOWNLOAD_STALL_TIMEOUT_MS);
            };

            this.nativeUpdater.checkAndUpdate().then(
                (result) => {
                    clearTimeout(timer);
                    this.nativeUpdater.onCheckResolved = null;
                    this.nativeUpdater.onProgress = null;
                    resolve(result);
                },
                (err) => {
                    clearTimeout(timer);
                    this.nativeUpdater.onCheckResolved = null;
                    this.nativeUpdater.onProgress = null;
                    reject(err);
                }
            );
        });
    }

    private async runWebUpdate(pending: PendingRestartEntry): Promise<void> {
        const bundleName = pending.bundle;
        if (!this.webChecker) {
            console.warn('[GameBundleUpdateView] webChecker 尚未在 Inspector 指定 略過 Web 版本檢查');
            return;
        }
        if (AppAssetBundle.getInstance(bundleName).hasCachedBundle()) {
            console.warn(`[GameBundleUpdateView] "${bundleName}" 本次 session 已載入過 版本檢查略過 需要重新整理頁面才會套用新版`);
            return;
        }
        this.setStatus('下載更新中...');
        this.updateProgress(0.05);
        const bundleUrl = await this.webChecker.resolveBundleUrl();
        this.updateProgress(0.1);
        const bundle = await AppAssetBundle.getInstance(bundleName).loadBundle(bundleUrl);
        this.updateProgress(0.2);

        // loadBundle 只載入 config/index，Web 真正的圖片、音效與場景資源
        // 是在 preloadScene 才下載。把這段的進度映射到 UI 的 20%~100%。
        if (pending.scene) {
            await new Promise<void>((resolve, reject) => {
                bundle.preloadScene(
                    pending.scene!,
                    (finished, total) => {
                        const ratio = total > 0 ? finished / total : 0;
                        this.updateProgress(0.2 + ratio * 0.8);
                    },
                    (err) => {
                        if (err) reject(err);
                        else {
                            this.updateProgress(1);
                            resolve();
                        }
                    }
                );
            });
        } else {
            this.updateProgress(1);
        }
    }

    private setStatus(text: string): void {
        if (this.statusLabel) this.statusLabel.string = text;
    }

    private updateProgress(percent: number): void {
        const ratio = Math.max(0, Math.min(1, percent));
        if (this.progressSlider) this.progressSlider.progress = ratio;
        if (this.progressTransform) this.progressTransform.width = this.barMaxWidth * ratio;
        if (this.progressLabel) this.progressLabel.string = `${(ratio * 100).toFixed(2)}%`;
    }

    private show(): void {
        if (this.panelRoot) this.panelRoot.active = true;
        this.updateProgress(0);
    }

    private hide(): void {
        if (this.panelRoot) this.panelRoot.active = false;
    }
}
