import { _decorator, Component, director, Label, Node, sp, Vec3 } from 'cc';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import StoreManager from '../store/StoreManager';
import AppAnimation from './AppAnimation';
import { GameViewAdapter } from './GameViewAdapter';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP } from '../AudioConfig';

const { ccclass, property } = _decorator;

/**
 * 恭喜獲得局數免費遊戲 轉場前的彈窗
 * 點畫面任何地方關閉彈窗
 * 呼叫 GameStore.completeWinFreeGame() 才繼續往下
 */
@ccclass('slot/1001/WinFreeGamePopupView')
export class WinFreeGamePopupView extends Component {
    @property(sp.Skeleton)
    backgroundSpine: sp.Skeleton = null!;

    @property(Node)
    title: Node = null!;

    @property(Node)
    popup: Node = null!;

    @property(Label)
    roundLabel: Label = null!;

    /** 點擊任何地方 */
    @property(Node)
    clickCatcher: Node = null!;

    private disposers: Array<() => void> = [];
    private dismissTimer: (() => void) | null = null; // 計時
    private transitionLoopTimer: (() => void) | null = null;
    private transitionLoopPlaying: boolean = false;
    private DEFAULT_AUTO_START_SEC = 10; // 先１０秒

    /** 自己的 scale */
    private popupBaseScale: Vec3 = new Vec3(1, 1, 1);
    private titleBaseScale: Vec3 = new Vec3(1, 1, 1);
    private spineBaseScale: Vec3 = new Vec3(1, 1, 1);

    protected override onLoad(): void {
        this.popupBaseScale = this.popup.scale.clone();
        if (this.title) this.titleBaseScale = this.title.scale.clone();
        if (this.backgroundSpine) this.spineBaseScale = this.backgroundSpine.node.scale.clone();
        this.applyAdapterOverride();

        this.clickCatcher?.on(Node.EventType.TOUCH_END, this.onDismiss, this);

        this.disposers.push(
            gameRuntimeEventBus.on(GAME_EVENT_TYPE.WIN_FREE_GAME_DATA_CHANGED, (event) => {
                if (event.data) this.show(event.data);
            })
        );

        const data = StoreManager.getInstance().getGameStore().winFreeGameData;
        if (data) this.show(data);
    }

    /** 直版跟橫版縮放 */
    private applyAdapterOverride(): void {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapter = scene.getComponentsInChildren(GameViewAdapter).find((a) => a.node.name === adapterName);
        if (!adapter) return;
        const lp = adapter.winFreeGamePopupLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) this.popup.setPosition(lp);
        // scale 抓初始值
        const sc = adapter.winFreeGamePopupScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) {
            this.popupBaseScale = new Vec3(this.popupBaseScale.x * sc.x, this.popupBaseScale.y * sc.y, this.popupBaseScale.z * sc.z);
        }

        const bgLp = adapter.winFreeGamePopupBgSpineLpos;
        if (bgLp && (bgLp.x !== 0 || bgLp.y !== 0 || bgLp.z !== 0)) this.backgroundSpine?.node.setPosition(bgLp);
        const bgSc = adapter.winFreeGamePopupBgSpineScale;
        if (bgSc && (bgSc.x !== 0 || bgSc.y !== 0 || bgSc.z !== 0)) {
            this.spineBaseScale = new Vec3(this.spineBaseScale.x * bgSc.x, this.spineBaseScale.y * bgSc.y, this.spineBaseScale.z * bgSc.z);
        }
    }

    private show(data: { freeRoundCount: number }): void {
        this.stopTransitionLoop();
        this.roundLabel.string = data.freeRoundCount + '';
        this.node.active = true;
        this.playEnter(); // 動效效果
        AppAudio.getInstance().playEffect(EFFECTSMAP.FG_POPUP);

        const loopCb = () => {
            this.transitionLoopTimer = null;
            this.transitionLoopPlaying = true;
            AppAudio.getInstance().playLoopEffect(EFFECTSMAP.TRANSITION_LOOP);
        };
        this.transitionLoopTimer = loopCb;
        this.scheduleOnce(loopCb, 1);

        if (this.dismissTimer) this.unschedule(this.dismissTimer);
        const cb = () => this.onDismiss();
        this.dismissTimer = cb;
        this.scheduleOnce(cb, this.DEFAULT_AUTO_START_SEC);
    }

    private onDismiss(): void {
        this.stopTransitionLoop();
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }
        this.playExit(() => {
            this.node.active = false;
            StoreManager.getInstance().getGameStore().completeWinFreeGame();
        });
    }

    private playEnter(): void {
        AppAnimation.stopScaleBreath(this.title);
        this.title?.setScale(this.titleBaseScale);
        this.popup?.setScale(this.popupBaseScale);
        this.backgroundSpine?.node.setScale(this.spineBaseScale);

        this.backgroundSpine.setAnimation(0, 'begin', false);
        this.backgroundSpine.setCompleteListener(() => {
            this.backgroundSpine.setCompleteListener(null!);
            this.backgroundSpine.setAnimation(0, 'loop', true);
        });

        AppAnimation.playPopIn(this.popup, this.popupBaseScale, {}, () => {
            // AppAnimation.playScaleBreath(this.popup);
            AppAnimation.playScaleBreath(this.title);
        });
    }

    private playExit(onComplete: () => void): void {
        AppAnimation.stopScaleBreath(this.title);
        this.backgroundSpine.setCompleteListener(null!);
        AppAnimation.playPopOut(this.backgroundSpine.node, this.spineBaseScale, {});
        AppAnimation.playPopOut(this.popup, this.popupBaseScale, {}, () => {
            if (this.node?.isValid) onComplete();
        });
    }

    protected override onDestroy(): void {
        this.disposers.forEach((d) => d());
        this.disposers = [];
        if (this.dismissTimer) this.unschedule(this.dismissTimer);
        this.stopTransitionLoop();
        // AppAnimation.stopScaleBreath(this.popup);
        AppAnimation.stopScaleBreath(this.title);
    }

    private stopTransitionLoop(): void {
        if (this.transitionLoopTimer) {
            this.unschedule(this.transitionLoopTimer);
            this.transitionLoopTimer = null;
        }
        if (!this.transitionLoopPlaying) return;
        this.transitionLoopPlaying = false;
        AppAudio.getInstance().stopLoopEffect(EFFECTSMAP.TRANSITION_LOOP);
    }
}
