import { _decorator, Button, Component, Label, Material, Node, Prefab, RealCurve, sp, SpriteFrame, UIOpacity, Vec3 } from 'cc';
import { SlotMachineView } from '../reel/view/SlotMachineView';
import type { SlotMachineModel } from '../reel/model/SlotMachineModel';
import { RollingNumberLabel } from './RollingNumberLabel';

const { ccclass, property } = _decorator;

@ccclass('slot/1001/GameViewAdapter')
export class GameViewAdapter extends Component {
    // runtime model（各 view 各自持有）
    slotMachineModel: SlotMachineModel = null!;

    // 彈窗根節點（BonusResult / BuyFeature / Jackpot / HsTransition 都會 reparent 到此）
    @property(Node)
    popupRoot: Node = null!;

    // 各彈窗的 prefab 路徑（留空則 fallback 到 GameContext 的預設路徑）
    @property({ tooltip: 'BonusResultView prefab 路徑（留空用預設）' })
    bonusResultPrefabPath: string = '';

    @property({ tooltip: 'JackpotView prefab 路徑（留空用預設）' })
    jackpotPrefabPath: string = '';

    @property({ tooltip: 'WinAnimationView prefab 路徑（留空用預設）' })
    winAnimationPrefabPath: string = '';

    @property({ tooltip: 'hsTransitionPanel prefab 路徑（留空用預設）' })
    hsTransitionPrefabPath: string = '';

    @property({ tooltip: 'buyFeaturePopup prefab 路徑（留空用預設）' })
    buyFeaturePrefabPath: string = '';

    // === 彈窗節點 transform 覆寫（給直版微調用，留 (0,0,0) 表示不覆寫）===
    @property({ tooltip: 'JackpotView bgSpine 位置覆寫（(0,0,0) = 不覆寫）' })
    jackpotBgSpineLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'JackpotView Jackpot 縮放覆寫（(0,0,0) = 不覆寫）' })
    jackpotBgSpineScale: Vec3 = new Vec3(1, 1, 1);

    @property({ tooltip: 'BonusResultView bgSpine 位置覆寫（(0,0,0) = 不覆寫）' })
    bonusResultBgSpineLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'BonusResultView bgSpine 縮放覆寫（(0,0,0) = 不覆寫）' })
    bonusResultBgSpineScale: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinAnimationView 內容子節點名稱（包住所有 spine 的 parent），留空則不覆寫' })
    winAnimationContentNodeName: string = '';

    @property({ tooltip: 'WinAnimationView 內容子節點位置覆寫（(0,0,0) = 不覆寫）' })
    winAnimationContentLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinAnimationView 內容子節點縮放覆寫（(0,0,0) = 不覆寫）' })
    winAnimationContentScale: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: "hsTransitionPanel spine 動畫名稱前綴（例如 '直版_'），留空不加" })
    hsTransitionAnimPrefix: string = '';

    @property({ tooltip: 'WinFreeGamePopupView popup 位置覆寫（(0,0,0) = 不覆寫）' })
    winFreeGamePopupLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinFreeGamePopupView popup 縮放覆寫 (0,0,0) = 不覆寫）' })
    winFreeGamePopupScale: Vec3 = new Vec3(1, 1, 1);

    @property({ tooltip: 'WinFreeGamePopupView backgroundSpine 位置覆寫（(0,0,0) = 不覆寫）' })
    winFreeGamePopupBgSpineLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinFreeGamePopupView backgroundSpine 縮放覆寫（(0,0,0) = 不覆寫）' })
    winFreeGamePopupBgSpineScale: Vec3 = new Vec3(1, 1, 1);

    // 背景
    @property(Node)
    bg: Node = null!;

    @property(Node)
    bgGreen: Node = null!;

    @property(Node)
    bgRed: Node = null!;

    @property(Node)
    bgBlue: Node = null!;

    @property(Node)
    reelBg: Node = null!;

    // 寶箱 spine
    @property(sp.Skeleton)
    chestRed: sp.Skeleton = null!;

    @property(sp.Skeleton)
    chestGreen: sp.Skeleton = null!;

    @property(sp.Skeleton)
    chestBlue: sp.Skeleton = null!;

    // 寶箱特效
    @property(sp.Skeleton)
    commonFxRed: sp.Skeleton = null!;

    @property(sp.Skeleton)
    commonFxGreen: sp.Skeleton = null!;

    @property(sp.Skeleton)
    commonFxBlue: sp.Skeleton = null!;

    // 金幣噴發

    @property(sp.Skeleton)
    chestCoinBurstGreen: sp.Skeleton = null!;

    @property(sp.Skeleton)
    chestCoinBurstRed: sp.Skeleton = null!;

    @property(sp.Skeleton)
    chestCoinBurstBlue: sp.Skeleton = null!;

    // 升級粒子
    @property(Prefab)
    upgradeParticlePrefab: Prefab = null!;

    // 轉輪
    @property(SlotMachineView)
    slotMachineView: SlotMachineView = null!;

    // 購買按鈕
    @property(Button)
    buyRandomBtn: Button = null!;

    @property(Label)
    buyRandomPriceLabel: Label = null!;

    @property(Button)
    buySuperBtn: Button = null!;

    @property(Label)
    buySuperPriceLabel: Label = null!;

    // Buy Feature 閃爍 spine（AB 測試 A 組達條件時播放）
    @property(sp.Skeleton)
    buyRandomFlashSpine: sp.Skeleton = null!;

    @property(sp.Skeleton)
    buySuperFlashSpine: sp.Skeleton = null!;

    // JP 標籤
    @property(RollingNumberLabel)
    jpGrandLabel: RollingNumberLabel = null!;

    @property(RollingNumberLabel)
    jpMajorLabel: RollingNumberLabel = null!;

    @property(RollingNumberLabel)
    jpMinorLabel: RollingNumberLabel = null!;

    @property(RollingNumberLabel)
    jpMiniLabel: RollingNumberLabel = null!;

    @property({ type: Label, tooltip: 'FG 累積倍率計數器 (frame_total_multiplier → Label 組件)' })
    frameTotalMultiplierLabel: Label = null!;

    @property({ type: sp.Skeleton, tooltip: 'FG 累積倍率計數器變動動效 (frame_total_multiplier → ui_mul spine)' })
    frameTotalMultiplierSpine: sp.Skeleton | null = null;

    // === win_bar（中獎累計條）===
    @property(Node)
    winBarNode: Node = null!;

    @property(sp.Skeleton)
    winBarSkel: sp.Skeleton = null!;

    @property(Label)
    winBarNumLabel: Label = null!;

    @property(Node)
    winBarMulNode: Node = null!;

    @property({ type: SpriteFrame, tooltip: '收球曲射原型用的球圖 先放張測試圖即可' })
    collectMulFrame: SpriteFrame = null!;

    @property({ type: [SpriteFrame], tooltip: '發射瞬間光暈 疊播圖片 全部拖進來即可' })
    collectAuraFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '發射瞬間第二層光暈 疊播圖片 緊接在 aura 之後播' })
    collectGlowFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '抵達終點閃光 疊播圖片 黑底圖需搭配 collectRemoveBlackBgMaterial' })
    collectFlareFrames: SpriteFrame[] = [];

    @property({ type: Material, tooltip: '閃光黑底圖去背用材質 套用在 collectFlareFrames 全部圖片上 留空則照原本混合模式顯示' })
    collectRemoveBlackBgMaterial: Material = null!;

    @property({ type: RealCurve, tooltip: '收球曲射：時間 0~1 對應水平/垂直移動進度 0~1' })
    collectMoveCurve: RealCurve = (() => {
        const curve = new RealCurve();
        curve.assignSorted([
            [0, { value: 0 }],
            [1, { value: 1 }],
        ]);
        return curve;
    })();

    @property({ type: RealCurve, tooltip: '收球曲射：時間 0~1 對應抬高比例 0~1，乘上曲度幅度 × 起訖距離（曲度幅度預設值見 CollectMulFly.ts，呼叫端可覆寫）' })
    collectHeightCurve: RealCurve = (() => {
        const curve = new RealCurve();
        curve.assignSorted([
            [0, { value: 0 }],
            [0.5, { value: 1 }],
            [1, { value: 0 }],
        ]);
        return curve;
    })();

    @property({ tooltip: '收球曲射：參考距離下的飛行時間（秒），實際時間會依起訖距離自動縮放，距離近的自動變快' })
    collectDuration: number = 0.25;

    @property(Label)
    winBarMulLabel: Label = null!;

    @property(UIOpacity)
    winBarMulOpacity: UIOpacity = null!;
}
